    "standardId": "c22_3_no1",
    "standardName": "CSA C22.3 No. 1",
    "edition": "2020",
    "clauseNumber": "5.7.3",
    "title": "Clearances of wires and conductors passing by or over buildings, signs,",
    "section": "5 Clearances, separations, and spacings",
    "page": 47,
    "text": "billboards, lamps, traffic signs, standards, and antennas (not attached)",
    "tablesReferenced": [],
