    "edition": "2020",
    "clauseNumber": "9.1.3",
    "title": "Ground electrodes and connections",
    "section": "9 Grounding methods for supply systems less than or equal to 22 kV and",
    "page": 76,
    "text": "",
    "tablesReferenced": [],
